import copy

def apply_patch(original,patch):
    result=copy.deepcopy(original) if isinstance(original,dict) else {}
    for key,value in patch.items():
        if value is None: result.pop(key,None)
        elif isinstance(value,dict): result[key]=apply_patch(result.get(key,{}),value)
        else: result[key]=copy.deepcopy(value)
    return result
